{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative Care in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="Holistic, whole-person care that blends evidence-based integrative medicine with personalized lifestyle plans. Book a VIP day or learn more." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="theme-root">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/services.html">Offerings</a>
        <a href="/approach.html">Our Approach</a>
        <a href="/conditions.html">Conditions</a>
        <a href="/about.html">About</a>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" aria-expanded="false" aria-label="Toggle navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section id="hero" class="hero">
      <div class="pattern-bg" aria-hidden="true"></div>
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1 class="hero-title">A practical, whole-person path back to balance</h1>
          <p class="hero-sub">At {{BUSINESS_NAME}} we blend integrative medicine, lifestyle coaching, and lab-informed insights to support lasting well-being — no quick fixes, just a clearer plan that fits your life.</p>
          <div class="hero-actions">
            <a class="button primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="button ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}, {{CREDENTIALS}}</a>
          </div>
        </div>
        <aside class="hero-card">
          <h3>Convenient: VIP Day option</h3>
          <p>A focused, single-day deep dive to create a personalized plan and next steps. Learn more on the pricing page.</p>
          <p class="muted">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        </aside>
      </div>
    </section>

    <!-- RITUAL -->
    <section id="ritual" class="section soft">
      <div class="wrap">
        <h2>Rituals that support whole-body health</h2>
        <p class="lede">Small, repeatable habits are the scaffolding for bigger change. We teach practical rituals rooted in nutrition, movement, sleep hygiene, and mindful breathing — customized to you.</p>
        <div class="grid">
          <div class="card">
            <h4>Morning resilience</h4>
            <p>Gentle practices to set circadian rhythm, energy, and focus without dramatic rules.</p>
          </div>
          <div class="card">
            <h4>Digestive rhythm</h4>
            <p>Simplified meal timing and supportive nutrients to ease digestion and reduce bloating over time.</p>
          </div>
          <div class="card">
            <h4>Recovery tonight</h4>
            <p>Sleep scaffolds and wind-down routines designed for restorative rest and daytime energy.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT -->
    <section id="what_to_expect" class="section light">
      <div class="wrap">
        <h2>What to expect from an initial engagement</h2>
        <ol class="expect-list">
          <li><strong>Comprehensive intake:</strong> A detailed conversation about history, lifestyle, and priorities.</li>
          <li><strong>Listening + education:</strong> We explain likely contributors and evidence-informed options — you decide what fits.</li>
          <li><strong>Personalized plan:</strong> A practical roadmap with rituals, targeted supplements (if appropriate), and optional labs for deeper insight.</li>
          <li><strong>Follow-up & adjustments:</strong> Measurement and course-correction are built in — health is iterative.</li>
        </ol>
        <p class="disclaimer">We emphasize education and incremental change. This is not a guarantee of cure; results vary and depend on many factors.</p>
      </div>
    </section>

    <!-- SCHEDULE -->
    <section id="schedule" class="section soft">
      <div class="wrap">
        <h2>Scheduling and formats</h2>
        <p>Choose what matches your life: virtual consults, in-person visits in {{CITY}}, or a focused VIP Day for deep assessment and planning.</p>
        <div class="grid">
          <div class="card">
            <h4>Initial Visit — 60 min</h4>
            <p>Thorough intake, baseline recommendations, and prioritized next steps.</p>
          </div>
          <div class="card">
            <h4>Follow-up — 30–45 min</h4>
            <p>Progress review, lab interpretation, and plan updates.</p>
          </div>
          <div class="card">
            <h4>VIP Day — 4–6 hours</h4>
            <p>An immersive, single-day experience to build a complete plan and schedule immediate next steps.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PRICING (teaser) -->
    <section id="pricing" class="section pricing-spotlight">
      <div class="wrap">
        <h2>Fair, transparent fees</h2>
        <p class="lede">We offer straightforward pricing and a VIP Day option for people who want an intensive plan in a single session. Full fees and package details are on our pricing page.</p>
        <div class="pricing-actions">
          <a class="button" href="/pricing.html">See full pricing</a>
          <a class="button ghost" href="/book.html">Request availability</a>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section id="faq" class="section light">
      <div class="wrap">
        <h2>Frequently asked questions</h2>
        <div class="faq-grid">
          <div class="faq-item">
            <h4>Do you use labs?</h4>
            <p>We can recommend and interpret optional labs to refine a plan. Labs are educational tools — we discuss implications and limits.</p>
          </div>
          <div class="faq-item">
            <h4>Are supplements required?</h4>
            <p>Supplements may be suggested when indicated, but the focus is often lifestyle first. We prioritize interventions with reasonable evidence and low risk.</p>
          </div>
          <div class="faq-item">
            <h4>What conditions do you address?</h4>
            <p>We commonly support stress, sleep disruption, digestive complaints, chronic inflammation, and low energy. See our Conditions page for more detail and disclaimers.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CTA FOOTER -->
    <section id="cta" class="section cta-band">
      <div class="wrap cta-inner">
        <div>
          <h2>Ready to build a clearer plan?</h2>
          <p>Schedule a call or book a VIP Day to create a focused, actionable roadmap tailored to you.</p>
        </div>
        <div class="cta-actions">
          <a class="button primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="button ghost" href="/contact.html">Contact staff</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap footer-inner">
      <div class="col">
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a>
      </address>
      </div>
      <div class="col">
        <nav class="footer-nav">
          <a href="/about.html">Who we are</a>
          <a href="/services.html">Services</a>
          <a href="/pricing.html">Fees</a>
          <a href="/book.html">Book</a>
        </nav>
      </div>
      <div class="col small">
        <p class="muted">Practitioner: {{PRACTITIONER_NAME}}, {{CREDENTIALS}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        <p class="muted">No guaranteed cures. Care emphasizes education, safety, and whole-person strategies.</p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
