{"path":"assets/css/styles.css","content":"/* Core styles for clinic_modern template */
:root{
  --bg:#f6fbf9;
  --card:#ffffff;
  --muted:#65737e;
  --accent1:#2a9d8f;
  --accent2:#006d77;
  --accent3:#83c5be;
  --text:#0b2b2e;
  --radius:12px;
  --wrap:1200px;
  --gap:20px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:var(--text); background:var(--bg); -webkit-font-smoothing:antialiased}
.wrap{max-width:var(--wrap);margin:0 auto;padding:24px}
.site-header{background:linear-gradient(180deg, rgba(255,255,255,0.9), rgba(255,255,255,0.8));backdrop-filter:blur(6px);border-bottom:1px solid rgba(10,20,20,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:12px}
.brand{font-weight:700;color:var(--accent2);text-decoration:none;font-size:1.1rem}
.main-nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.main-nav a{color:var(--text);text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:white;padding:8px 14px}
.nav-toggle{display:none;background:none;border:0;font-size:1.2rem}

.hero{position:relative;overflow:hidden;padding:48px 0}
.pattern-bg{position:absolute;inset:0;background-image:url('/assets/img/pattern.svg');background-repeat:repeat;opacity:0.12;mix-blend-mode:multiply}
.hero-inner{display:flex;gap:32px;align-items:stretch}
.hero-copy{flex:1;padding:40px;background:linear-gradient(180deg, rgba(255,255,255,0.65), rgba(255,255,255,0.5));border-radius:var(--radius);box-shadow:0 6px 18px rgba(6,20,20,0.06)}
.hero-title{font-size:2rem;margin:0 0 12px}
.hero-sub{margin:0 0 18px;color:var(--muted)}
.hero-actions{display:flex;gap:12px}
.button{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;border:1px solid transparent}
.button.primary{background:linear-gradient(90deg,var(--accent2),var(--accent1));color:white}
.button.ghost{background:transparent;border-color:rgba(10,20,20,0.06)}
.hero-card{width:320px;padding:22px;background:var(--card);border-radius:12px;box-shadow:0 8px 30px rgba(10,20,20,0.06)}
.hero-card h3{margin-top:0}
.muted{color:var(--muted);font-size:0.9rem}

.section{padding:40px 0}
.section.soft{background:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.9))}
.section.light{background:transparent}
.lede{color:var(--muted);max-width:70%}
.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:20px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(10,20,20,0.04)}
.expect-list{list-style:decimal;margin:18px 0;padding-left:18px;color:var(--muted)}
.disclaimer{font-size:0.9rem;color:var(--muted);margin-top:8px}
.pricing-spotlight{background:linear-gradient(90deg, rgba(40,120,110,0.04), rgba(20,80,80,0.02))}
.pricing-actions{margin-top:18px;display:flex;gap:12px}
.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.faq-item{background:var(--card);padding:16px;border-radius:10px}
.cta-band{background:linear-gradient(90deg,var(--accent3),rgba(255,255,255,0.02));color:var(--text);padding:30px 0}
.cta-inner{display:flex;align-items:center;justify-content:space-between}
.cta-actions{display:flex;gap:12px}
.site-footer{border-top:1px solid rgba(10,20,20,0.04);padding:24px 0;background:transparent}
.footer-inner{display:flex;gap:20px;align-items:flex-start}
.footer-inner .col{flex:1}
.footer-inner .small{flex:1.2}
.footer-nav{display:flex;flex-direction:column;gap:8px}

@media(max-width:900px){
  .hero-inner{flex-direction:column}
  .grid{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .nav-toggle{display:block}
  .main-nav{position:absolute;right:24px;top:64px;background:var(--card);padding:12px;border-radius:10px;box-shadow:0 8px 30px rgba(10,20,20,0.08);display:none;flex-direction:column}
  .main-nav.show{display:flex}
  .wrap{padding:16px}
}

/* Small utility */
.muted small{color:var(--muted)}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var btn = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.main-nav');
  if(btn && nav){
    btn.addEventListener('click', function(){
      var open = nav.classList.toggle('show');
      btn.setAttribute('aria-expanded', open? 'true':'false');
    });
  }

  // Smooth scroll for internal links
  document.addEventListener('click', function(e){
    var a = e.target.closest('a');
    if(!a) return;
    var href = a.getAttribute('href') || '';
    if(href.startsWith('#')){
      var id = href.slice(1);
      var el = document.getElementById(id);
      if(el){
        e.preventDefault();
        window.scrollTo({top: el.offsetTop - 60, behavior: 'smooth'});
      }
    }
  });

  // Simple link sanitizer for primary CTA
  var ctas = document.querySelectorAll('a.cta, a.button.primary');
  ctas.forEach(function(c){
    var href = c.getAttribute('href') || '';
    if(href.indexOf('javascript:')!==-1){
      c.setAttribute('href','#');
    }
  });
})();"} 
